import{_ as n,a0 as o,w as l,s as f,I as a,x as t,a1 as r,A as i,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const F=JSON.parse('{"title":"使用 Fstransform 转换文件系统 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Fstransform 转换文件系统 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Fstransform 转换文件系统 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Fstransform 转换文件系统 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180813 Convert file systems with Fstransform","title":"使用 Fstransform 转换文件系统","tag":"201808","desc":""},"relativePath":"201808/20180813 Convert file systems with Fstransform.md","filePath":"[post].md"}'),p={name:"201808/20180813 Convert file systems with Fstransform.md"};function m(u,s,g,h,b,x){const e=o("Link");return l(),f("div",null,[s[18]||(s[18]=a("h1",{id:"使用-fstransform-转换文件系统",tabindex:"-1"},[t("使用 Fstransform 转换文件系统 "),a("a",{class:"header-anchor",href:"#使用-fstransform-转换文件系统","aria-label":"Permalink to “使用 Fstransform 转换文件系统”"},"​")],-1)),s[19]||(s[19]=a("p",null,[a("img",{src:"https://fedoramagazine.org/wp-content/uploads/2018/08/converting-filesystems-816x345.jpg",alt:""})],-1)),a("p",null,[s[1]||(s[1]=t("很少有人知道他们可以将文件系统从一种类型转换为另一种类型而不会丢失数据（即非破坏性的）。这可能听起来像魔术，但 ",-1)),r(e,{href:"https://github.com/cosmos72/fstransform"},{default:i(()=>[...s[0]||(s[0]=[t("Fstransform",-1)])]),_:1}),s[2]||(s[2]=t(" 可以几乎以任意组合将 ext2、ext3、ext4、jfs、reiserfs 或 xfs 分区转换成另一类型。更重要的是，它可以直接执行，而无需格式化或复制数据。除此之外，还有一点好处：Fstransform 也可以处理 ntfs、btrfs、fat 和 exfat 分区。",-1))]),s[20]||(s[20]=d('<h3 id="在运行之前" tabindex="-1">在运行之前 <a class="header-anchor" href="#在运行之前" aria-label="Permalink to “在运行之前”">​</a></h3><p>Fstransform 存在一些警告和限制，因此强烈建议在尝试转换之前进行备份。此外，使用 Fstransform 时需要注意一些限制：</p><ul><li>你的 Linux 内核必须支持源文件系统和目标文件系统。听起来很明显，如果你想使用 ext2、ext3、ext4、reiserfs、jfs 和 xfs 分区，这样不会出现风险。Fedora 支持所有分区，所以没问题。</li><li>将 ext2 升级到 ext3 或 ext4 不需要 Fstransform。请使用 Tune2fs。</li><li>源文件系统的设备必须至少有 5％ 的可用空间。</li><li>你需要在开始之前卸载源文件系统。</li><li>源文件系统存储的数据越多，转换的时间就越长。实际速度取决于你的设备，但预计它大约为每分钟 1GB。大量的硬链接也会降低转换速度。</li><li>虽然 Fstransform 被证明是稳定的，但请备份源文件系统上的数据。</li></ul><h3 id="安装说明" tabindex="-1">安装说明 <a class="header-anchor" href="#安装说明" aria-label="Permalink to “安装说明”">​</a></h3><p>Fstransform 已经是 Fedora 的一部分。使用以下命令安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install fstransform</span></span></code></pre></div><h3 id="转换" tabindex="-1">转换 <a class="header-anchor" href="#转换" aria-label="Permalink to “转换”">​</a></h3><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/08/Screenshot_20180805_230116.png" alt=""></p><p><code>fstransform</code> 命令的语法非常简单：<code>fstransform &lt;源设备&gt; &lt;目标文件系统&gt;</code>。请记住，它需要 root 权限才能运行，所以不要忘记在开头添加 <code>sudo</code>。这是一个例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo fstransform /dev/sdb1 ext4</span></span></code></pre></div><p>请注意，无法转换根文件系统，这是一种安全措施。请改用测试分区或实验性 USB 盘。与此同时，Fstransform 会在控制台中有许多辅助输出。最有用的部分是预计完成时间，让你随时了解该过程需要多长时间。同样，在几乎空的驱动器上的几个小文件将使 Fstransform 在一分钟左右完成其工作，而更多真实世界的任务可能需要数小时的等待时间。</p><h3 id="更多支持的文件系统" tabindex="-1">更多支持的文件系统 <a class="header-anchor" href="#更多支持的文件系统" aria-label="Permalink to “更多支持的文件系统”">​</a></h3><p>如上所述，可以尝试在 ntfs、btrfs、fat 和 exfat 分区使用 Fstransform。这些类型是早期实验性的，没有人能保证完美转换。尽管如此，还是有许多成功案例，你可以通过在测试分区上使用示例数据集测试 Fstransform 来添加自己的成功案例。可以使用 <code>--force-untested-file-systems</code> 参数启用这些额外的文件系统：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo fstransform /dev/sdb1 ntfs --force-untested-file-systems</span></span></code></pre></div><p>有时，该过程可能会因错误而中断。请放心再次执行命令 —— 它可能最终会在两、三次尝试后完成转换。</p><hr>',16)),a("p",null,[s[4]||(s[4]=t("via: ",-1)),r(e,{href:"https://fedoramagazine.org/transform-file-systems-in-linux/"},{default:i(()=>[...s[3]||(s[3]=[t("https://fedoramagazine.org/transform-file-systems-in-linux/",-1)])]),_:1})]),a("p",null,[s[9]||(s[9]=t("作者：",-1)),r(e,{href:"https://fedoramagazine.org/author/atolstoy/"},{default:i(()=>[...s[5]||(s[5]=[t("atolstoy",-1)])]),_:1}),s[10]||(s[10]=t(" 选题：",-1)),r(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[6]||(s[6]=[t("lujun9972",-1)])]),_:1}),s[11]||(s[11]=t(" 译者：",-1)),r(e,{href:"https://github.com/geekpi"},{default:i(()=>[...s[7]||(s[7]=[t("geekpi",-1)])]),_:1}),s[12]||(s[12]=t(" 校对：",-1)),r(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[8]||(s[8]=[t("wxy",-1)])]),_:1})]),a("p",null,[s[15]||(s[15]=t("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[13]||(s[13]=[t("LCTT",-1)])]),_:1}),s[16]||(s[16]=t(" 原创编译，",-1)),r(e,{href:"https://linux.cn/"},{default:i(()=>[...s[14]||(s[14]=[t("Linux中国",-1)])]),_:1}),s[17]||(s[17]=t(" 荣誉推出",-1))])])}const T=n(p,[["render",m]]);export{F as __pageData,T as default};
